package com.g4t0xx.forge;
import android.app.*;import android.content.*;import android.os.*;import android.speech.*;import android.speech.tts.*;import org.json.*;import java.util.*;
final class Voice implements RecognitionListener {
 final MainActivity activity;final Handler main=new Handler(Looper.getMainLooper());TextToSpeech tts;SpeechRecognizer recognizer;boolean ready,listening,wake,awaitingCommand,offline=true;String status="Voz iniciando";String chosen="";
 Voice(MainActivity a){activity=a;tts=new TextToSpeech(a,s->{ready=s==TextToSpeech.SUCCESS;status=ready?"Voz pronta":"Motor de voz indisponível";if(ready){tts.setLanguage(new Locale("pt","BR"));chosen=a.getSharedPreferences("voice",0).getString("voice","");select(chosen);tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){if(wake)main.postDelayed(()->listen(true,offline),500);}public void onError(String id){}});}});}
 JSONObject info()throws Exception{JSONArray voices=new JSONArray();if(ready&&tts.getVoices()!=null){List<android.speech.tts.Voice> list=new ArrayList<>(tts.getVoices());list.sort(Comparator.comparing(v->v.getLocale().toLanguageTag()+v.getName()));for(android.speech.tts.Voice v:list)if(v.getLocale().getLanguage().equals("pt")||v.getLocale().getLanguage().equals("en"))voices.put(Json.obj("id",v.getName(),"language",v.getLocale().toLanguageTag(),"offline",!v.isNetworkConnectionRequired(),"quality",v.getQuality()));}return Json.obj("ready",ready,"voices",voices,"selected",chosen,"listening",listening,"wake",wake,"status",status,"recognizer",SpeechRecognizer.isRecognitionAvailable(activity),"offline_recognizer",Build.VERSION.SDK_INT>=31&&SpeechRecognizer.isOnDeviceRecognitionAvailable(activity));}
 void select(String id){if(!ready)return;if(tts.getVoices()!=null){if(id.isEmpty())for(android.speech.tts.Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals("pt")&&!v.isNetworkConnectionRequired()){id=v.getName();break;}for(android.speech.tts.Voice v:tts.getVoices())if(v.getName().equals(id)){tts.setVoice(v);chosen=id;activity.getSharedPreferences("voice",0).edit().putString("voice",id).apply();}}}
 void synthesize(String text,String name){main.post(()->{if(!ready){emit("error","Voz não pronta");return;}select(name);java.io.File file=new java.io.File(activity.getFilesDir(),"workspace/forge-voz.wav");file.getParentFile().mkdirs();int status=tts.synthesizeToFile(text,null,file,"export-voice");if(status==TextToSpeech.ERROR)emit("error","Não foi possível sintetizar voz");});}
 void speak(String text,String voice,float rate,boolean offlineOnly){main.post(()->{if(!ready){emit("error","Motor de voz ainda não está pronto");return;}select(voice);if(offlineOnly&&tts.getVoice()!=null&&tts.getVoice().isNetworkConnectionRequired()){emit("error","Selecione uma voz offline instalada");return;}tts.setSpeechRate(Math.max(.5f,Math.min(2f,rate)));if(recognizer!=null)recognizer.cancel();listening=false;int code=tts.speak(text.substring(0,Math.min(3900,text.length())),TextToSpeech.QUEUE_FLUSH,null,UUID.randomUUID().toString());if(code==TextToSpeech.ERROR)emit("error","Não foi possível falar com essa voz");});}
 void listen(boolean wakeMode,boolean offlineOnly){main.post(()->{
  wake=wakeMode;offline=offlineOnly;if(activity.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},31);emit("error","Permita o microfone e toque novamente para ouvir");return;}
  if(listening)return;if(!SpeechRecognizer.isRecognitionAvailable(activity)){emit("error","Instale ou ative um reconhecedor de voz Android");wake=false;return;}
  if(recognizer!=null)recognizer.destroy();boolean onDevice=Build.VERSION.SDK_INT>=31&&SpeechRecognizer.isOnDeviceRecognitionAvailable(activity);if(offlineOnly&&!onDevice){emit("error","Reconhecimento offline indisponível. Instale o idioma no serviço de voz ou use ditado online.");wake=false;return;}
  recognizer=onDevice?SpeechRecognizer.createOnDeviceSpeechRecognizer(activity):SpeechRecognizer.createSpeechRecognizer(activity);recognizer.setRecognitionListener(this);Intent intent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"pt-BR").putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,offlineOnly).putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);listening=true;status=wake?"Diga Forge, seguido do pedido":"Ouvindo";recognizer.startListening(intent);emit("status",status);
 });}
 void stop(){main.post(()->{wake=false;listening=false;if(recognizer!=null){recognizer.cancel();recognizer.destroy();recognizer=null;}if(tts!=null)tts.stop();status="Voz pausada";emit("status",status);});}
 void emit(String kind,String text){try{activity.emit("voice",Json.obj("kind",kind,"text",text));}catch(Exception ignored){}}
 public void onReadyForSpeech(Bundle b){emit("status",status);}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){listening=false;}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}
 public void onError(int code){listening=false;status="Reconhecimento: "+code;emit("status",status);if(wake&&(code==SpeechRecognizer.ERROR_NO_MATCH||code==SpeechRecognizer.ERROR_SPEECH_TIMEOUT))main.postDelayed(()->listen(true,offline),1200);else if(wake){wake=false;emit("error","Escuta por nome parou ("+code+"). Toque para ativar novamente.");}}
 public void onResults(Bundle b){listening=false;ArrayList<String> list=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);String text=list==null||list.isEmpty()?"":list.get(0);if(wake){if(awaitingCommand&&!text.isEmpty()){awaitingCommand=false;emit("command",text);main.postDelayed(()->{if(wake)listen(true,offline);},900);return;}String lower=text.toLowerCase(Locale.ROOT);int pos=lower.indexOf("forge");if(pos<0)pos=lower.indexOf("forje");if(pos>=0){String command=text.substring(pos+5).replaceFirst("^[, :]+","");if(command.isEmpty()){awaitingCommand=true;emit("activated","Pode falar");}else emit("command",command);}main.postDelayed(()->{if(wake)listen(true,offline);},900);}else if(!text.isEmpty())emit("transcript",text);}
 void close(){stop();if(tts!=null)tts.shutdown();}
}
